<template>
 <section class="research-workspace" aria-label="研究工作台">
  <header class="research-header"><div><div class="research-eyebrow">RESEARCH / WT</div><h1>研究</h1><p>把资料、假设、数据和实验放在一起。</p></div><div class="research-actions"><el-button :loading="loading" @click="load">刷新</el-button><el-button :disabled="!canEdit" @click="newReport">添加资料</el-button><el-button type="primary" :disabled="!canEdit" @click="newProject">新建研究</el-button></div></header>
  <el-alert v-if="error" :title="error" type="error" :closable="false" class="research-error"/>
  <nav class="research-sections" aria-label="研究内容"><button v-for="item in sections" :key="item.id" :class="{active:section===item.id}" :aria-pressed="section===item.id" @click="section=item.id">{{item.label}}<small>{{sectionCount(item.id)}}</small></button></nav>

  <ResearchAutomation v-if="section==='factors'" :data="factorAutomation"/>
  <div v-if="section==='projects'" class="research-layout">
   <aside class="research-projects" aria-label="研究项目列表"><div class="research-list-heading"><strong>研究项目</strong><span>{{projects.length}}</span></div><el-input v-model="projectSearch" placeholder="查找研究项目" clearable aria-label="查找研究项目"/><button v-for="item in filteredProjects" :key="item.id" class="research-project" :class="{selected:item.id===project?.id}" @click="selectProject(item)"><strong>{{item.title}}</strong><small>{{kindLabel(item.kind)}} · v{{item.version||1}}</small><span>{{item.hypothesis||'填写一个可以检验的问题'}}</span></button><p v-if="!filteredProjects.length" class="research-empty">从研报创建研究，或新建一个时序实验。</p></aside>
   <article v-if="project" class="research-project-main">
    <div class="research-project-heading"><div><small>{{kindLabel(project.kind)}} / v{{project.version||1}}</small><h2>{{project.title}}</h2></div><el-button :disabled="!canEdit" :loading="saving" @click="saveProject">保存研究</el-button></div>
    <nav class="research-tabs" aria-label="项目步骤"><button v-for="item in projectTabs" :key="item.id" :class="{active:tab===item.id}" :aria-pressed="tab===item.id" @click="tab=item.id">{{item.label}}</button></nav>
    <div v-if="tab==='hypothesis'" class="research-tab-content">
     <div v-if="linkedReport" class="research-linked-source"><div><small>{{sourceTypeLabel(linkedReport.source_type)}} · 原始资料</small><h3>{{linkedReport.title}}</h3><p>{{linkedReport.organization||linkedReport.authors?.join('、')}} · {{linkedReport.published_at||'日期未说明'}}</p></div><el-button @click="readReport(linkedReport)">阅读原文</el-button></div>
     <SourceSummary v-if="linkedReport" :summary="linkedReport.core_summary" :job="linkedReport.summary_job" :can-request="canEdit" @request="requestSummary(linkedReport)"/>
     <p v-else class="research-note">先关联一份资料，或直接写下自己的研究假设。</p>
     <div class="research-hypothesis"><div class="research-section-heading"><div><h3>我的研究假设</h3><p>这是你的判断，与上方原文提炼分别保存。</p></div><small v-if="projectDirty">有未保存修改</small></div><el-form label-position="top" :disabled="!canEdit"><el-form-item label="要检验什么，怎样算失效？"><el-input type="textarea" :rows="3" v-model="projectDraft.hypothesis" placeholder="写清现象、解释与失效条件。" aria-label="研究假设"/></el-form-item><el-form-item label="研究笔记"><el-input type="textarea" :rows="3" v-model="projectDraft.notes" placeholder="记录你的推理、疑问和下一步。" aria-label="研究笔记与原文页码"/></el-form-item><details class="research-project-settings"><summary>项目名称与关联资料</summary><el-form-item label="研究标题"><el-input v-model="projectDraft.title" maxlength="120" aria-label="研究标题"/></el-form-item><el-form-item label="关联资料"><el-select v-model="projectDraft.report_id" clearable placeholder="选择资料" aria-label="关联研报"><el-option v-for="item in reports" :key="item.id" :value="item.id" :label="item.title"/></el-select></el-form-item></details></el-form></div>
     <p v-if="project.template_id" class="research-method-note">方法实验采用内置双均线模板。它与资料中的原文公式分别保存。</p>
    </div>
    <div v-else-if="tab==='data'" class="research-tab-content">
     <h3>数据湖与 WT 历史</h3><p class="research-note">{{lake.message||'数据湖覆盖正在读取'}}<span v-if="lake.updated_at"> · {{formatTime(lake.updated_at)}}</span></p><el-table v-if="lake.datasets?.length" :data="lake.datasets" max-height="260" empty-text="数据湖暂无已登记行情"><el-table-column prop="symbol" label="合约" min-width="145"/><el-table-column label="周期" width="95"><template #default="{row}">{{periodLabel(row.period)}}</template></el-table-column><el-table-column prop="rows" label="条数" width="85"/><el-table-column label="实际覆盖" min-width="200"><template #default="{row}">{{row.start}} — {{row.end}}</template></el-table-column></el-table><p class="research-note">数据湖下载后，使用既有导入流程写入 WT。实验从下面配置的 WT 历史副本读取。</p><h3>我的实验规则</h3><p class="research-note">这里保存项目规则；原文公式在“资料与假设”中展示。</p><el-input v-model="projectDraft.formula" type="textarea" :rows="3" :disabled="!canEdit" placeholder="写清输入、计算、调仓和退出规则。" aria-label="研究公式"/>
     <div class="research-code-heading"><div><strong>{{projectDraft.template_id?'内置实验规则':'研究规则快照'}}</strong><small>{{projectDraft.template_id?'代码只读，参数在每次实验中固定。':'该项目只登记研究资料，尚未选择可执行模板。'}}</small></div></div>
     <div class="research-code"><CodeEditor v-model="projectDraft.code" :options="{mode:'python',lineWrapping:false,readOnly:true}"/></div>
     <p class="research-note">保存研究后，再到“实验”选择数据和时间。行情来自现有 WT 历史目录；数据湖补数仍在历史数据管理。</p>
     <router-link to="/history" class="research-text-link">查看历史数据与补数 →</router-link>
    </div>
    <FactorLibrary v-else-if="tab==='factors'" :project="project" :projects="projects" :factors="factors" :builtins="factorBuiltins" :experiments="factorExperiments" :native-experiments="experiments" :datasets="datasets" :reports="reports" :can-edit="canEdit" @refresh="load"/>
    <ResearchPortfolio v-else-if="tab==='portfolio'" :request="request" :project-id="project.id" :can-edit="canEdit"/>
    <ResearchWorkflow v-else-if="tab==='checks'" :project="project" :factors="factors" :experiments="factorExperiments" :workflows="researchWorkflows" :can-edit="canEdit" @refresh="load"/>
    <div v-else-if="tab==='experiments'" class="research-tab-content">
     <div class="research-section-heading"><div><h3>实验记录</h3><p>保存版本、参数与数据，再交给 WT 原生回测。</p></div><el-button type="primary" :disabled="!canEdit" @click="configureExperiment">配置实验</el-button></div>
     <ExperimentTable :rows="projectExperiments" @open="openExperiment" @cancel="cancelExperiment" :can-edit="canEdit"/>
    </div>
    <div v-else-if="tab==='diagnostics'" class="research-tab-content"><div class="research-section-heading"><div><h3>先检查结果从哪里来</h3><p>诊断来自实际实验输出，不填充演示收益。</p></div></div><template v-if="projectExperiments.length"><label class="research-label">选择实验</label><el-select v-model="diagnosticId" placeholder="选择一次实验" aria-label="诊断实验" @change="loadDiagnostic"><el-option v-for="item in projectExperiments" :key="item.id" :value="item.id" :label="experimentLabel(item)"/></el-select><ExperimentResult v-if="diagnostic" :detail="diagnostic" compact/></template><p v-else class="research-empty">还没有实验。先配置数据与时间，再运行一次。</p></div>
    <div v-else class="research-tab-content"><div class="research-section-heading"><div><h3>成果阅读</h3><p>每份成果都能追到原文、项目版本和实验配置。</p></div></div><div class="research-result-list"><button v-for="item in projectResults" :key="item.id" @click="openExperiment(item)"><strong>{{item.title||project.title}}</strong><span>{{formatTime(item.created_at)}} · {{statusLabel(item.status)}}</span><small>查看实验结果与阅读报告 →</small></button><p v-if="!projectResults.length" class="research-empty">完成实验后，这里会出现成果入口。</p></div></div>
   </article>
   <div v-else class="research-welcome"><WtIcon name="document"/><h2>先提出一个可以检验的问题</h2><p>阅读研报，记录公式和假设，再用已有数据复现。</p><article v-if="reports.length" class="research-first-paper"><small>从一份公开研究开始 · {{reports[0].organization}}</small><h3>{{reports[0].title}}</h3><p>{{excerpt(reports[0].body)}}</p><div><el-button @click="readReport(reports[0])">阅读这份研报</el-button><el-button type="primary" :disabled="!canEdit" @click="newProject(reports[0])">从研报开始</el-button></div></article><div><el-button @click="section='reports'">浏览全部资料</el-button><el-button :disabled="!canEdit" @click="newProject">新建研究</el-button></div></div>
  </div>

  <div v-else-if="section==='reports'" class="research-library"><div class="research-section-heading"><div><h2>研究资料</h2><p>先看核心内容，再按需阅读原文。</p></div><el-input v-model="reportSearch" placeholder="搜索机构、标题或主题" clearable aria-label="搜索研报"/></div><nav class="research-source-types" aria-label="资料来源类型"><button v-for="item in sourceTypes" :key="item.id" :class="{active:reportSourceType===item.id}" :aria-pressed="reportSourceType===item.id" @click="reportSourceType=item.id">{{item.label}}<small>{{sourceCount(item.id)}}</small></button></nav><div class="research-report-filters"><el-select v-model="reportProvider" clearable placeholder="全部机构" aria-label="研报机构筛选"><el-option v-for="item in reportSources" :key="item.id" :value="item.id" :label="item.name"/></el-select><el-select v-model="reportType" clearable placeholder="全部类型" aria-label="研报类型筛选"><el-option v-for="item in reportFilters.report_types" :key="item" :value="item" :label="item"/></el-select><el-select v-model="reportTopic" clearable placeholder="全部品种主题" aria-label="研报主题筛选"><el-option v-for="item in reportFilters.topics" :key="item" :value="item" :label="item"/></el-select></div><p class="research-note">官网分类原样保留。品种主题来自标题规则，仅用于筛选。</p><div class="research-source-list"><div v-for="item in reportSources" :key="item.id"><strong>{{item.name}}</strong><span>{{item.state||'尚未采集'}} · {{item.last_success?formatTime(item.last_success):'等待首次采集'}}</span><small v-if="item.error">{{item.error}}</small></div><el-button :disabled="!canEdit" :loading="collecting" @click="collectReports">采集官网最新研报</el-button></div><div class="research-paper-grid"><article v-for="item in filteredReports" :key="item.id" class="research-paper"><small>{{sourceTypeLabel(item.source_type)}} · {{item.organization||item.authors?.join('、')||'个人资料'}} · {{item.published_at||'日期未说明'}}</small><h3>{{item.title}}</h3><small v-if="item.provider">{{fetchLabel(item)}} · {{item.report_type}}<span v-if="item.report_type_origin==='title_rule'">（标题判断）</span></small><p v-if="item.source_category" class="research-category">官网：{{item.source_category}}</p><div v-if="item.topic_tags?.length" class="research-topic-tags"><span v-for="tag in item.topic_tags" :key="tag">{{tag}}</span></div><p class="research-card-question">{{item.core_summary?.overview?.question?.text||summaryLabel(item)}}</p><p>{{item.core_summary?.overview?.conclusion?.text||excerpt(item.body||item.error||'尚无可读正文，请打开原文。')}}</p><p class="research-note">摘要：{{summaryLabel(item)}}<span v-if="item.summary_job?.retry_after && (item.summary_job?.budget_exhausted || item.summary_job?.status==='failed' && (item.summary_job?.attempts||0)<3)"> · 重试 {{formatTime(item.summary_job.retry_after)}}</span></p><p v-if="item.summary_job?.error" class="research-note">{{item.summary_job.error}}</p><p class="research-note">因子研究：{{factorLabel(item)}}<span v-if="item.factor_screen?.retry_after && item.factor_screen?.status==='waiting_budget'"> · 恢复 {{formatTime(item.factor_screen.retry_after)}}</span></p><p v-if="item.factor_screen?.reason" class="research-note">{{item.factor_screen.reason}}</p><small v-if="item.core_summary">摘要 v{{item.core_summary.version}} · {{item.core_summary.formula_state==='explicit'?'含原文公式':'未提取明确公式'}}</small><div><el-button @click="readReport(item)">阅读</el-button><el-button :disabled="!canEdit" @click="newProject(item)">创建研究</el-button><el-button text :disabled="!canEdit" @click="editReport(item)">保存个人副本</el-button></div></article></div><p v-if="!filteredReports.length" class="research-empty">添加公开研报链接、上传原文，或粘贴资料。</p></div>
  <FactorLibrary v-else-if="section==='factors'" :projects="projects" :factors="factors" :builtins="factorBuiltins" :experiments="factorExperiments" :native-experiments="experiments" :datasets="datasets" :reports="reports" :can-edit="canEdit" @refresh="load"/>
  <div v-else-if="section==='experiments'" class="research-all"><div class="research-section-heading"><div><h2>全部实验</h2><p>查看队列、运行进度和失败原因。</p></div></div><ExperimentTable :rows="experiments" :can-edit="canEdit" @open="openExperiment" @cancel="cancelExperiment"/></div>
  <div v-else class="research-all"><div class="research-section-heading"><div><h2>成果</h2><p>阅读报告，核对实际成交和诊断。</p></div></div><div class="research-result-list"><button v-for="item in completedExperiments" :key="item.id" @click="openExperiment(item)"><strong>{{projectTitle(item.project_id)}}</strong><span>{{formatTime(item.created_at)}} · {{statusLabel(item.status)}}</span><small>{{datasetTitle(item.dataset)}} · 阅读结果 →</small></button><p v-if="!completedExperiments.length" class="research-empty">实验完成后，成果会显示在这里。</p></div></div>

  <el-dialog v-model="projectDialog" title="新建研究" width="min(620px,94vw)"><el-form label-position="top" @submit.prevent="createProject"><el-form-item label="研究名称（可修改）"><el-input v-model="newProjectForm.title" maxlength="120" aria-label="新研究名称"/></el-form-item><el-form-item label="关联研报"><el-select v-model="newProjectForm.report_id" clearable aria-label="新研究关联研报"><el-option v-for="item in reports" :key="item.id" :value="item.id" :label="item.title"/></el-select></el-form-item><el-form-item label="起步方式"><el-select v-model="newProjectForm.template_id" aria-label="研究模板"><el-option v-for="item in templates" :key="item.id" :value="item.id" :label="item.name||item.label||item.title"/></el-select></el-form-item><p class="research-note">首期使用内置时序模板验证方法，不复现原报告的全部模型或收益。</p><el-form-item label="要检验的假设"><el-input type="textarea" :rows="3" v-model="newProjectForm.hypothesis" aria-label="新研究假设"/></el-form-item></el-form><template #footer><el-button @click="projectDialog=false">取消</el-button><el-button type="primary" :loading="saving" :disabled="!newProjectForm.title.trim()" @click="createProject">创建研究</el-button></template></el-dialog>
  <el-dialog v-model="reportDialog" :title="reportForm.id?'编辑阅读笔记':'添加资料'" width="min(740px,94vw)"><el-form label-position="top"><div class="research-form-grid"><el-form-item label="标题"><el-input v-model="reportForm.title" maxlength="200" aria-label="研报标题"/></el-form-item><el-form-item label="资料类型"><el-select v-model="reportForm.source_type" aria-label="资料类型"><el-option v-for="item in sourceTypes.filter(x=>x.id!=='all')" :key="item.id" :value="item.id" :label="item.label"/></el-select></el-form-item><el-form-item label="机构或作者"><el-input v-model="reportForm.organization" aria-label="研报机构"/></el-form-item><el-form-item label="发布日期"><el-date-picker v-model="reportForm.published_at" type="date" value-format="YYYY-MM-DD" aria-label="研报发布日期"/></el-form-item><el-form-item label="原文链接"><el-input v-model="reportForm.source_url" placeholder="https://…" aria-label="研报原文链接"/></el-form-item></div><el-form-item label="原文正文或摘录"><el-input v-model="reportForm.body" type="textarea" :rows="7" aria-label="研报正文"/></el-form-item><el-form-item label="个人阅读笔记"><el-input v-model="reportForm.notes" type="textarea" :rows="3" aria-label="研报阅读笔记"/></el-form-item><el-form-item label="附加原文文件（PDF、TXT、Markdown，最多 10 MiB）"><input type="file" accept=".pdf,.txt,.md" @change="selectAttachment" aria-label="上传研报原文"/><small v-if="reportForm.attachment">{{reportForm.attachment.filename}}</small></el-form-item></el-form><template #footer><el-button @click="reportDialog=false">取消</el-button><el-button type="primary" :loading="saving" :disabled="!reportForm.title.trim()" @click="saveReport">保存资料</el-button></template></el-dialog>
  <el-dialog v-model="readingReport" :title="activeReport?.title||'资料阅读'" width="min(1050px,96vw)" class="research-reader"><template v-if="activeReport"><div class="research-reader-meta"><span>{{sourceTypeLabel(activeReport.source_type)}} · {{activeReport.organization||activeReport.authors?.join('、')}} · {{activeReport.published_at||'日期未说明'}}</span><a v-if="safeLink(activeReport.canonical_url||activeReport.source_url)" :href="activeReport.canonical_url||activeReport.source_url" target="_blank" rel="noopener noreferrer">打开原始来源 ↗</a><a v-if="safeAttachment(activeReport.attachment_url)" :href="activeReport.attachment_url" target="_blank" rel="noopener noreferrer">打开附件 ↗</a></div><SourceSummary :summary="activeReport.core_summary" :job="activeReport.summary_job" :can-request="canEdit" @request="requestSummary(activeReport)"/><details class="research-original"><summary>阅读原文、摘录与 PDF</summary><iframe v-if="safeAttachment(activeReport.attachment_url)&&isPdf(activeReport)" :src="activeReport.attachment_url" sandbox="allow-same-origin" title="研报原文 PDF" class="research-pdf"/><el-alert v-if="activeReport.fetch_state==='failed'" :title="activeReport.error" type="warning" :closable="false"/><p v-if="activeReport.text_state==='unavailable'" class="research-note">正文未提取，请打开原件阅读。</p><p v-if="activeReport.text_extraction" class="research-note">{{activeReport.text_extraction.status==='ready'?'文字由已保存PDF提取，原件保持不变。':activeReport.text_extraction.error}}</p><pre class="research-prose">{{activeReport.body||activeReport.derived_text?.body||'正文尚未保存，请打开原文或附件。'}}</pre></details><details class="research-original"><summary>个人阅读笔记</summary><pre class="research-prose research-notes">{{activeReport.notes||'尚无阅读笔记。'}}</pre></details></template><template #footer><el-button @click="readingReport=false">关闭</el-button><el-button type="primary" :disabled="!canEdit" @click="readingReport=false;newProject(activeReport)">从这份资料创建研究</el-button></template></el-dialog>
  <el-dialog v-model="experimentDialog" title="配置复现实验" width="min(690px,94vw)"><el-form label-position="top"><el-form-item label="WT 历史数据集"><el-select v-model="experimentForm.dataset" filterable @change="selectDataset" aria-label="实验数据集"><el-option v-for="item in datasets" :key="item.id" :value="item.id" :label="item.label||item.code+' · '+item.period"/></el-select></el-form-item><div v-if="selectedDataset" class="research-coverage"><strong>{{selectedDataset.code}} · {{periodLabel(selectedDataset.period)}}</strong><span>实际覆盖 {{stamp(selectedDataset.start)}} — {{stamp(selectedDataset.end)}}</span><span>{{selectedDataset.rows?.toLocaleString()}} 条 · 交易日与夜盘按原数据保存</span></div><div class="research-form-grid"><el-form-item label="开始日期"><el-date-picker v-model="experimentForm.start" type="date" value-format="YYYYMMDD" aria-label="实验开始日期"/></el-form-item><el-form-item label="结束日期"><el-date-picker v-model="experimentForm.end" type="date" value-format="YYYYMMDD" aria-label="实验结束日期"/></el-form-item><el-form-item label="初始资金"><el-input-number v-model="experimentForm.capital" :min="1" :max="1000000000" :controls="false" aria-label="实验初始资金"/></el-form-item><el-form-item label="价格滑点"><el-input-number v-model="experimentForm.slippage" :min="0" :max="100" :precision="0" :controls="false" aria-label="实验滑点"/></el-form-item></div><template v-if="project?.template_id"><h3>模板参数</h3><div class="research-form-grid"><el-form-item v-for="item in parameterFields" :key="item.key" :label="item.label"><el-input-number v-model="experimentForm.params[item.key]" :min="item.min||1" :max="item.max||10000" :precision="0" :controls="false" :aria-label="item.label"/></el-form-item></div></template><p class="research-note">使用已保存的项目版本。结果由 WT 原生回测生成；K 线输入按收盘事件处理。任务与交易、采集进程分开。</p></el-form><template #footer><el-button @click="experimentDialog=false">取消</el-button><el-button type="primary" :loading="launching" :disabled="!experimentForm.dataset" @click="runExperiment">保存配置并运行</el-button></template></el-dialog>
  <el-drawer v-model="detailOpen" title="实验与成果" size="min(1060px,98vw)"><div v-if="detailLoading" class="research-empty">正在读取实验结果…</div><template v-else-if="detail"><div class="research-detail-heading"><div><small>{{detail.project?.title}}</small><h2>{{statusLabel(detail.experiment?.status)}} · {{detail.experiment?.id}}</h2></div><el-button @click="refreshDetail">刷新结果</el-button></div><ExperimentResult :detail="detail"/><a v-if="safeAttachment(detail.read_url)" :href="detail.read_url" target="_blank" rel="noopener noreferrer" class="research-read-result">打开完整成果阅读页 ↗</a><div v-if="detail.report" class="research-reference"><div><small>原文资料</small><strong>{{detail.report.title}}</strong></div><el-button @click="readReport(detail.report)">阅读原文</el-button></div><details class="research-config"><summary>固定的实验配置</summary><pre>{{JSON.stringify(detail.experiment?.config||detail.experiment,null,2)}}</pre></details></template></el-drawer>
 </section>
</template>

<script>
import {defineAsyncComponent} from 'vue'
import WtIcon from '@/components/common/WtIcon.vue'
import ExperimentTable from './ResearchExperimentTable.vue'
import ExperimentResult from './ResearchExperimentResult.vue'
import FactorLibrary from './ResearchFactorLibrary.vue'
import ResearchAutomation from './ResearchAutomation.vue'
import ResearchWorkflow from './ResearchWorkflow.vue'
import SourceSummary from './ResearchSourceSummary.vue'
import ResearchPortfolio from './ResearchPortfolio.vue'
const CodeEditor=defineAsyncComponent(()=>import('@/components/common/CodeEditor.vue'))
const reportEmpty=()=>({title:'',organization:'',published_at:'',source_url:'',source_type:'report',body:'',notes:''})
const statusNames={queued:'排队中',preparing:'准备数据',running:'运行中',completed:'已完成',failed:'失败',cancelled:'已取消',canceled:'已取消',interrupted:'已中断',stopped:'已停止'}
export default {
 name:'ResearchWorkspace',components:{WtIcon,CodeEditor,ExperimentTable,ExperimentResult,FactorLibrary,ResearchWorkflow,ResearchAutomation,SourceSummary,ResearchPortfolio},
 data:()=>({section:'projects',tab:'hypothesis',sections:[{id:'projects',label:'研究项目'},{id:'reports',label:'研究资料'},{id:'factors',label:'因子库'},{id:'experiments',label:'实验'},{id:'results',label:'成果'}],projectTabs:[{id:'hypothesis',label:'资料与假设'},{id:'data',label:'数据与公式'},{id:'factors',label:'因子实验'},{id:'portfolio',label:'多因子趋势'},{id:'checks',label:'研究检查'},{id:'experiments',label:'实验'},{id:'diagnostics',label:'诊断'},{id:'results',label:'成果'}],reports:[],reportSources:[],reportFilters:{report_types:[],topics:[]},reportProvider:'',reportType:'',reportTopic:'',reportSourceType:'all',sourceTypes:[{id:'all',label:'全部'},{id:'report',label:'金工研报'},{id:'blog',label:'博客'},{id:'paper',label:'论文'}],sourceDetail:null,researchWorkflows:[],factorAutomation:{},factors:[],factorBuiltins:[],factorExperiments:[],collecting:false,projects:[],experiments:[],datasets:[],templates:[],lake:{state:'unknown',datasets:[],message:''},canEdit:false,loading:false,saving:false,launching:false,error:'',projectSearch:'',reportSearch:'',reportSearchResults:null,project:null,projectDraft:{},projectDialog:false,newProjectForm:{title:'',report_id:'',template_id:'',hypothesis:''},reportDialog:false,reportForm:reportEmpty(),readingReport:false,activeReport:null,experimentDialog:false,experimentForm:{dataset:'',start:'',end:'',capital:1000000,slippage:1,params:{}},detailOpen:false,detailLoading:false,detail:null,diagnosticId:'',diagnostic:null}),
 computed:{
  filteredProjects(){const q=this.projectSearch.toLowerCase();return this.projects.filter(x=>(x.title+' '+x.hypothesis).toLowerCase().includes(q))},
  filteredReports(){return (this.reportSearchResults??this.reports.filter(x=>this.matchesReport(x,{query:this.reportSearch,provider:this.reportProvider,report_type:this.reportType,topic:this.reportTopic}))).filter(x=>this.reportSourceType==='all'||(x.source_type||'report')===this.reportSourceType)},
  projectDirty(){return this.project&&['title','report_id','hypothesis','formula','notes','code','template_id'].some(key=>(this.projectDraft[key]||'')!==(this.project[key]||''))},
  linkedReport(){return this.sourceDetail?.id===this.projectDraft.report_id?this.sourceDetail:this.reports.find(x=>x.id===this.projectDraft.report_id)},
  projectExperiments(){return this.experiments.filter(x=>x.project_id===this.project?.id)},projectResults(){return this.projectExperiments.filter(x=>x.status==='completed')},completedExperiments(){return this.experiments.filter(x=>x.status==='completed')},
  selectedDataset(){return this.datasets.find(x=>x.id===this.experimentForm.dataset)},
  parameterFields(){const template=this.templates.find(x=>x.id===this.project?.template_id);return template?.parameters||[{key:'fast',label:'快均线周期',default:5,min:2,max:200},{key:'slow',label:'慢均线周期',default:20,min:3,max:500},{key:'lots',label:'目标手数',default:1,min:1,max:20}]}
 },
 watch:{'projectDraft.report_id'(){this.loadSourceDetail()},reportSearch(){this.searchReports()},reportProvider(){this.searchReports()},reportType(){this.searchReports()},reportTopic(){this.searchReports()}},
 mounted(){if(['projects','library','factors'].includes(this.$route.query.section))this.section=this.$route.query.section;this.load();this._poll=setInterval(()=>{if(this.section==='factors'||this.experiments.some(x=>['queued','preparing','running'].includes(x.status))||this.factorExperiments.some(x=>x.status==='running')||this.researchWorkflows.some(x=>['comparing','testing'].includes(x.status))||this.collecting||this.reports.some(x=>['queued','running'].includes(x.summary_job?.status)))this.poll()},2500)},beforeUnmount(){clearInterval(this._poll);clearTimeout(this._searchTimer)},
 methods:{
  matchesReport(item,filters){const q=String(filters.query||'').toLowerCase();return (!filters.provider||item.provider===filters.provider)&&(!filters.report_type||item.report_type===filters.report_type)&&(!filters.topic||item.topic_tags?.includes(filters.topic))&&[item.title,item.organization,item.authors?.join(' '),item.body,item.core_summary?.overview?.question?.text,item.core_summary?.overview?.conclusion?.text].filter(Boolean).join(' ').toLowerCase().includes(q)},
  searchReports(){clearTimeout(this._searchTimer);this.reportSearchResults=null;const body={query:this.reportSearch,provider:this.reportProvider,report_type:this.reportType,topic:this.reportTopic};const key=JSON.stringify(body);this._searchKey=key;if(!Object.values(body).some(Boolean))return;this._searchTimer=setTimeout(async()=>{try{const result=await this.request('report_search',body);if(this._searchKey===key){const ids=new Set(result.reports.map(x=>x.id));this.reportSearchResults=[...result.reports,...this.reports.filter(x=>!ids.has(x.id)&&this.matchesReport(x,body))]}}catch(error){this.error=error.message}},300)},
  sourceTypeLabel(value){return {report:'金工研报',blog:'博客',paper:'论文'}[value||'report']||'研究资料'},sourceCount(type){return type==='all'?this.reports.length:this.reports.filter(x=>(x.source_type||'report')===type).length},
  async loadSourceDetail(){const id=this.projectDraft.report_id;this.sourceDetail=null;if(!id)return;try{const result=await this.request('report_detail',{report_id:id});if(this.projectDraft.report_id===id)this.sourceDetail=result.report}catch(error){this.error=error.message}},
  async requestSummary(report){try{const result=await this.request('report_summary_request',{report_id:report.id,refresh:Boolean(report.core_summary||['failed','waiting_text'].includes(report.summary_job?.status))});if(['unavailable','waiting_text'].includes(result.summary_job.status)){this.$message.info(result.summary_job.reason);return}this.$message.success('核心提炼已排队，不会修改你的研究假设');await this.poll()}catch(error){this.$message.error(error.message)}},
  async syncSourceViews(){for(const key of ['sourceDetail','activeReport']){const current=this[key];if(!current)continue;const fresh=this.reports.find(x=>x.id===current.id);if(!fresh)continue;if(fresh.core_summary&&(fresh.core_summary.version!==current.core_summary?.version||fresh.core_summary.status!==current.core_summary?.status)){const result=await this.request('report_detail',{report_id:current.id});if(this[key]?.id===current.id)this[key]=result.report}else {current.summary_job=fresh.summary_job;current.factor_screen=fresh.factor_screen}}},
  async request(action,body={}){const response=await fetch('/mgr/research/'+action,{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const value=await response.json();if(!response.ok||value.result<0)throw new Error(value.message||'研究请求失败');return value},
  async load(){this.loading=true;this.error='';try{const data=await this.request('list',{include_catalog:false});this.applyList(data);if(!this.project&&this.projects.length){const id=localStorage.getItem('wt.research.project');this.selectProject(this.projects.find(x=>x.id===id)||this.projects[0])}await this.syncSourceViews()}catch(error){this.error=error.message;return}finally{this.loading=false}try{const data=await this.request('catalog');this.datasets=data.datasets||[];this.templates=data.templates||[];this.lake=data.lake||{state:'unknown',datasets:[],message:'尚未读取数据湖目录'}}catch(error){this.error=error.message}},
  applyList(data){this.reports=data.reports||[];this.projects=data.projects||[];this.experiments=data.experiments||[];this.factors=data.factors||[];this.factorBuiltins=data.factor_builtins||[];this.factorExperiments=data.factor_experiments||[];this.reportSources=data.report_sources||[];this.reportFilters=data.report_filters||this.reportFilters;this.researchWorkflows=data.research_workflows||[];this.factorAutomation=data.factor_automation||{};if('datasets' in data)this.datasets=data.datasets||[];if('templates' in data)this.templates=data.templates||[];if('lake' in data)this.lake=data.lake||{state:'unknown',datasets:[],message:'尚未读取数据湖目录'};this.canEdit=Boolean(data.can_edit)},
  async poll(){if(this._polling)return;this._polling=true;try{this.applyList(await this.request('list',{include_catalog:false}));await this.syncSourceViews();if(this.detailOpen&&this.detail&&['queued','preparing','running'].includes(this.detail.experiment?.status))await this.refreshDetail();if(this.tab==='diagnostics'&&this.diagnosticId&&['queued','preparing','running'].includes(this.diagnostic?.experiment?.status))await this.loadDiagnostic()}catch(error){this.error=error.message}finally{this._polling=false}},
  sectionCount(id){return id==='factors'?this.factors.length:id==='reports'?this.reports.length:id==='projects'?this.projects.length:id==='experiments'?this.experiments.length:this.completedExperiments.length},
  kindLabel(value){return {timeseries:'时序研究',cross_section:'截面研究',arbitrage:'套利研究'}[value]||value||'时序研究'},
  statusLabel(value){return statusNames[value]||value||'待开始'},
  formatTime(value){if(!value)return'—';if(typeof value==='string'&&!/^\d+$/.test(value))return value.replace('T',' ').slice(0,19);const n=Number(value);return new Date(n<1e12?n*1000:n).toLocaleString('zh-CN',{hour12:false})},
  stamp(value){const text=String(value||'');return text.length>=8?text.slice(0,4)+'-'+text.slice(4,6)+'-'+text.slice(6,8)+(text.length>=12?' '+text.slice(8,10)+':'+text.slice(10,12):''):'—'},
  periodLabel(value){return {tick:'Tick',m1:'1 分钟',m5:'5 分钟',d:'日线'}[value]||value},excerpt(value){const text=String(value||'').trim();return text.length>150?text.slice(0,150)+'…':text||'打开原文阅读。'},
  safeLink(value){try{return ['http:','https:'].includes(new URL(value).protocol)}catch{return false}},safeAttachment(value){return typeof value==='string'&&value.startsWith('/mgr/research/')&&!value.includes('..')},isPdf(report){return String(report.attachment_filename||report.attachment_name||report.attachment?.filename||report.attachment_url||'').toLowerCase().split('?')[0].endsWith('.pdf')},
  projectTitle(id){return this.projects.find(x=>x.id===id)?.title||'研究实验'},datasetTitle(id){return this.datasets.find(x=>x.id===id)?.label||id||'固定数据副本'},experimentLabel(item){return this.formatTime(item.created_at)+' · '+this.statusLabel(item.status)+' · '+item.id.slice(0,8)},
  selectProject(item){this.sourceDetail=null;this.project=item;this.projectDraft=JSON.parse(JSON.stringify(item));this.diagnosticId='';this.diagnostic=null;localStorage.setItem('wt.research.project',item.id);this.section='projects';this.tab='hypothesis'},
  newProject(report){if(!this.canEdit)return;this.newProjectForm={title:report?.id?report.title+' · 方法实验':'',report_id:report?.id||this.reports[0]?.id||'',kind:'timeseries',template_id:this.templates[0]?.id||'',hypothesis:''};this.projectDialog=true},
  async createProject(){this.saving=true;try{const data=await this.request('project_save',this.newProjectForm);await this.load();this.selectProject(data.project);this.projectDialog=false;this.$message.success('研究已创建')}catch(error){this.$message.error(error.message)}finally{this.saving=false}},
  async saveProject(){this.saving=true;try{const data=await this.request('project_save',this.projectDraft);this.project=data.project;this.projectDraft=JSON.parse(JSON.stringify(data.project));this.projects=this.projects.map(x=>x.id===data.project.id?data.project:x);this.$message.success('研究版本已保存')}catch(error){this.$message.error(error.message)}finally{this.saving=false}},
  summaryLabel(item){
   const job=item.summary_job
   if(item.core_summary?.status==='ready')return '已完成'
   if(item.text_state==='unsupported_source')return '原文来源未支持'
   if(job?.budget_exhausted)return '今日摘要额度用完，次日继续'
   if(job?.status==='failed')return (job.attempts||0)>=3?'失败，自动重试已停止':'失败，等待自动重试'
   if(job)return {queued:'排队中',running:'正在提炼',waiting_text:'缺少可读原文',skipped_scope:'超出研究范围'}[job.status]||job.status
   if(item.text_state==='unavailable'||item.body_scope==='none')return '缺少可读原文'
   return item.core_summary?'原文已更新，等待重新提炼':'等待进入摘要队列'
  },
  factorLabel(item){return {awaiting_extraction:'公式提炼排队中',waiting_budget:'今日额度用完，次日继续',unsupported_source:'原文来源未支持',waiting_text:'缺少完整原文',not_selected:'初筛未选中',not_reproducible:'原文无法按现有条件复现',research_rejected:'检验未通过',research_accepted:'研究通过，等待后续验证',failed:'处理失败',out_of_scope:'超出研究范围',reference_only:'方法参考资料'}[item.factor_screen?.status]||item.factor_screen?.status||'尚未进入因子筛选'},
  fetchLabel(item){return {text_ready:'正文已提取',pdf_ready:'PDF已保存',metadata_only:'仅目录信息',unsupported_source:'原文来源未支持',failed:'原文抓取失败'}[item.fetch_state]||'个人资料'},async collectReports(){this.collecting=true;try{await this.request('report_collect');this.$message.success('采集已启动，请稍后刷新');setTimeout(()=>{this.collecting=false;this.load()},60000)}catch(error){this.collecting=false;this.$message.error(error.message)}},newReport(){if(!this.canEdit)return;this.reportForm=reportEmpty();this.reportDialog=true},editReport(item){this.reportForm=JSON.parse(JSON.stringify(item));for(const key of ['id','public','readonly','core_summary','summary_job'])delete this.reportForm[key];this.reportDialog=true},async readReport(item){try{const data=await this.request('report_detail',{report_id:item.id});this.activeReport=data.report;this.readingReport=true}catch(error){this.$message.error(error.message)}},
  async selectAttachment(event){const file=event.target.files?.[0];if(!file)return;if(file.size>10*1024*1024||!(/\.(pdf|txt|md)$/i.test(file.name))){this.$message.error('请选择最多 10 MiB 的 PDF、TXT 或 Markdown');event.target.value='';return}try{const content=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=reject;reader.readAsDataURL(file)});this.reportForm.attachment={filename:file.name,content_base64:content}}catch{this.$message.error('读取附件失败')}},
  async saveReport(){this.saving=true;try{await this.request('report_save',this.reportForm);this.reportDialog=false;await this.load();this.$message.success('研报资料已保存')}catch(error){this.$message.error(error.message)}finally{this.saving=false}},
  configureExperiment(){if(!this.project.template_id){this.$message.warning('请为项目选择内置研究模板后再运行');return;}if(this.projectDirty){this.$message.warning('请先保存研究修改，再创建实验');return;}this.experimentForm={dataset:this.datasets[0]?.id||'',start:'',end:'',capital:1000000,slippage:1,params:{}};for(const field of this.parameterFields)this.experimentForm.params[field.key]=field.default??1;this.selectDataset();this.experimentDialog=true},
  selectDataset(){const item=this.selectedDataset;if(item){this.experimentForm.start=String(item.start).slice(0,8);this.experimentForm.end=String(item.end).slice(0,8)}},
  async runExperiment(){if(!this.experimentForm.start||!this.experimentForm.end||this.experimentForm.start>this.experimentForm.end){this.$message.error('请选择有效的实验起止日期');return}this.launching=true;try{const body={...this.experimentForm,project_id:this.project.id,start:Number(this.experimentForm.start),end:Number(this.experimentForm.end),params:this.project.template_id?this.experimentForm.params:{}};const data=await this.request('experiment_run',body);this.experimentDialog=false;this.tab='experiments';await this.poll();await this.openExperiment(data.experiment);this.$message.success('实验已进入队列')}catch(error){this.$message.error(error.message)}finally{this.launching=false}},
  async openExperiment(item){this.detailOpen=true;this.detail=null;this.detailLoading=true;try{this.detail=await this.request('experiment_detail',{experiment_id:item.id})}catch(error){this.$message.error(error.message)}finally{this.detailLoading=false}},
  async refreshDetail(){if(!this.detail?.experiment?.id)return;try{this.detail=await this.request('experiment_detail',{experiment_id:this.detail.experiment.id})}catch(error){this.$message.error(error.message)}},
  async loadDiagnostic(){try{this.diagnostic=await this.request('experiment_detail',{experiment_id:this.diagnosticId})}catch(error){this.$message.error(error.message)}},
  async cancelExperiment(item){try{await this.request('experiment_cancel',{experiment_id:item.id});await this.poll()}catch(error){this.$message.error(error.message)}}
 }
}
</script>

